flowDot:
digraph G {
  rankdir=TB; bgcolor="transparent"; nodesep=0.35; ranksep=0.45; newrank=true;
  node [fontname="Helvetica", fontsize=18, margin="0.2,0.1", style="rounded,filled", penwidth=2];
  edge [fontname="Helvetica", fontsize=16, penwidth=1.5, color="#6B7280"];
  Q [label="Large, several valid approaches,\narchitectural or multi-file?", shape=diamond, style="rounded,filled", fillcolor="#EDE9FE", color="#7C3AED"];
  PLAN [label="⭐ Plan mode: explore read-only,\ncompare approaches, write a plan", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  DIRECT [label="⭐ Direct execution\n(clear, small scope)", shape=box, style="rounded,filled", fillcolor="#D1FAE5", color="#059669"];
  EXPL [label="⭐ Verbose discovery →\nExplore subagent (summary back)", shape=box, style="rounded,filled", fillcolor="#CCFBF1", color="#0D9488"];
  APPROVE [label="Approve the plan", shape=diamond, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  EXEC [label="⭐ Execute the planned approach\n(plan → direct)", shape=box, style="rounded,filled", fillcolor="#D1FAE5", color="#059669"];
  DONE [label="Done without rework", shape=box, style="rounded,filled", fillcolor="#EDE9FE", color="#7C3AED"];
  DIRECTBUG [label="✗ direct on an\narchitectural task", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  OVERPLAN [label="✗ plan mode for a\none-line fix", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  NOEXPLORE [label="✗ discovery floods the\nmain context", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  NEVEREXEC [label="✗ plan approved,\nnever executed", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  EXPL -> Q [label="lots to discover first", style=dashed];
  Q -> PLAN [label="yes"]; Q -> DIRECT [label="no"]; { rank=same; PLAN; } { rank=same; DIRECT; } PLAN -> DIRECT [style=invis];
  PLAN -> APPROVE; APPROVE -> EXEC [label="approve"]; APPROVE -> PLAN [label="keep planning", style=dashed];
  EXEC -> DONE; DIRECT -> DONE;
  { rank=same; DIRECTBUG; OVERPLAN; } { rank=same; NOEXPLORE; NEVEREXEC; } DIRECTBUG -> NOEXPLORE [style=invis]; OVERPLAN -> NEVEREXEC [style=invis];
  DONE -> DIRECTBUG [style=invis];
  KEY [shape=plain, label=<<TABLE BORDER="0" CELLBORDER="1" CELLSPACING="3" CELLPADDING="3"><TR><TD COLSPAN="2" BORDER="0" ALIGN="LEFT"><FONT POINT-SIZE="18"><B>Key</B></FONT></TD></TR><TR><TD BGCOLOR="#EDE9FE" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">the decision</FONT></TD></TR><TR><TD BGCOLOR="#DBEAFE" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">plan mode</FONT></TD></TR><TR><TD BGCOLOR="#D1FAE5" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">direct execution</FONT></TD></TR><TR><TD BGCOLOR="#CCFBF1" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">Explore subagent</FONT></TD></TR><TR><TD BGCOLOR="#FFFFFF" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">bug (a distractor)</FONT></TD></TR><TR><TD WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"><FONT POINT-SIZE="16">⭐</FONT></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">named by the exam guide (TS 3.4 p.14)</FONT></TD></TR></TABLE>>];
  DIRECTBUG -> KEY [style=invis];
}

